import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"Introducción","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/introduction.md","filePath":"es/guide/introduction.md","lastUpdated":1793173149000}`),a={name:`es/guide/introduction.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="introduccion" tabindex="-1">Introducción <a class="header-anchor" href="#introduccion" aria-label="Permalink to “Introducción”">​</a></h1><h2 id="acerca-de-sudoku" tabindex="-1">Acerca de Sudoku <a class="header-anchor" href="#acerca-de-sudoku" aria-label="Permalink to “Acerca de Sudoku”">​</a></h2><p><strong>Sudoku — El clásico rompecabezas de números, perfectamente elaborado.</strong></p><p><img src="/screenshot-ipad-main.png" alt="Sudoku en funcionamiento en el iPad"></p><p>Vuelve a descubrir el atemporal puzle de lógica que tanto te gusta, refinado para los dispositivos modernos con controles fluidos, temas preciosos y una capacidad de repetición infinita. Tanto si es tu primera partida como si eres un experto veterano, esta es la experiencia de Sudoku que estabas esperando.</p><h2 id="funciones-principales" tabindex="-1">Funciones principales <a class="header-anchor" href="#funciones-principales" aria-label="Permalink to “Funciones principales”">​</a></h2><h3 id="🔢-jugabilidad-autentica" tabindex="-1">🔢 <strong>Jugabilidad auténtica</strong> <a class="header-anchor" href="#🔢-jugabilidad-autentica" aria-label="Permalink to “🔢 Jugabilidad auténtica”">​</a></h3><p>Fiel a las reglas clásicas: rellena una cuadrícula de 9×9 de modo que cada fila, cada columna y cada caja de 3×3 contenga los dígitos del 1 al 9 exactamente una vez. Toca para colocar números, usa las notas a lápiz para los candidatos y deja que la lógica te lleve hasta la solución.</p><h3 id="🎯-5-niveles-de-dificultad" tabindex="-1">🎯 <strong>5 niveles de dificultad</strong> <a class="header-anchor" href="#🎯-5-niveles-de-dificultad" aria-label="Permalink to “🎯 5 niveles de dificultad”">​</a></h3><p>Cinco dificultades cuidadosamente calibradas, con distinto número de celdas dadas:</p><table tabindex="0"><thead><tr><th>Nivel</th><th>Celdas dadas</th><th>Descripción</th></tr></thead><tbody><tr><td>Fácil</td><td>45</td><td>Ideal para principiantes y partidas rápidas</td></tr><tr><td>Medio</td><td>36</td><td>Un reto equilibrado para jugadores ocasionales</td></tr><tr><td>Difícil</td><td>31</td><td>Requiere técnicas de deducción lógica</td></tr><tr><td>Experto</td><td>27</td><td>Para solucionadores con experiencia que buscan una prueba de verdad</td></tr><tr><td>Maestro</td><td>24</td><td>El desafío definitivo: solo para los más valientes</td></tr></tbody></table><p>Cada puzle se genera de forma única: no hay dos partidas iguales.</p><h3 id="📱-app-universal" tabindex="-1">📱 <strong>App universal</strong> <a class="header-anchor" href="#📱-app-universal" aria-label="Permalink to “📱 App universal”">​</a></h3><p>Una sola compra funciona en iPhone, iPad y Mac. Controles nativos en cada plataforma: gestos táctiles en iOS, ratón y teclado en Mac. Tu progreso se sincroniza mediante iCloud en todos tus dispositivos.</p><p><img src="/screenshot-iphone-main.png" alt="Sudoku en el iPhone"></p><p><img src="/screenshot-mac-difficulty.png" alt="Sudoku en el Mac"></p><h3 id="💡-pistas-y-notas" tabindex="-1">💡 <strong>Pistas y notas</strong> <a class="header-anchor" href="#💡-pistas-y-notas" aria-label="Permalink to “💡 Pistas y notas”">​</a></h3><ul><li><strong>Pista</strong>: ¿atascado? Consigue una pista que revela una celda correcta sin arruinar todo el puzle.</li><li><strong>Lápiz (notas)</strong>: activa el modo lápiz para anotar dígitos candidatos en las celdas vacías. Las marcas a lápiz de las celdas relacionadas (misma fila, columna o caja) se borran solas cuando colocas un número.</li><li><strong>Comprobación de errores</strong>: resaltado opcional de las entradas incorrectas para que aprendas de tus fallos.</li><li><strong>Deshacer</strong>: compatibilidad completa con deshacer; recupera cualquier movimiento, en cualquier momento.</li></ul><h3 id="🏆-desafio-diario" tabindex="-1">🏆 <strong>Desafío diario</strong> <a class="header-anchor" href="#🏆-desafio-diario" aria-label="Permalink to “🏆 Desafío diario”">​</a></h3><p>Un puzle nuevo cada día con el nivel de dificultad Maestro. Encadena días seguidos y sigue tu progreso diario en la vista de calendario de Estadísticas.</p><h3 id="📊-estadisticas" tabindex="-1">📊 <strong>Estadísticas</strong> <a class="header-anchor" href="#📊-estadisticas" aria-label="Permalink to “📊 Estadísticas”">​</a></h3><p>Sigue tu rendimiento: partidas totales jugadas, porcentaje de victorias, racha actual, mejor racha y desgloses por dificultad, incluyendo mejores tiempos y medias. Sincronizado mediante iCloud.</p><h3 id="🎨-8-temas-preciosos" tabindex="-1">🎨 <strong>8 temas preciosos</strong> <a class="header-anchor" href="#🎨-8-temas-preciosos" aria-label="Permalink to “🎨 8 temas preciosos”">​</a></h3><p>Personaliza tu tablero con ocho temas de color elaborados a mano: Classic, Midnight, Paper, Forest, Ocean, Sunset, Lavender y Rose. Cada tema ofrece una experiencia visual distinta sin perder una legibilidad excelente.</p><h3 id="☁️-sincronizacion-con-icloud" tabindex="-1">☁️ <strong>Sincronización con iCloud</strong> <a class="header-anchor" href="#☁️-sincronizacion-con-icloud" aria-label="Permalink to “☁️ Sincronización con iCloud”">​</a></h3><p>Tus ajustes, estadísticas, partidas guardadas y el progreso del desafío diario se sincronizan automáticamente en todos tus dispositivos Apple mediante CloudKit. Empieza una partida en el iPhone y continúa en el Mac.</p><h3 id="🎮-game-center" tabindex="-1">🎮 <strong>Game Center</strong> <a class="header-anchor" href="#🎮-game-center" aria-label="Permalink to “🎮 Game Center”">​</a></h3><p>Compite en las clasificaciones con tus mejores tiempos de finalización y gana logros: First Solve, Easy Clear, Medium Clear, Hard Clear, Expert Clear, Master Clear y Flawless (completar sin pistas ni errores).</p><h3 id="🔇-limpio-y-sin-anuncios" tabindex="-1">🔇 <strong>Limpio y sin anuncios</strong> <a class="header-anchor" href="#🔇-limpio-y-sin-anuncios" aria-label="Permalink to “🔇 Limpio y sin anuncios”">​</a></h3><p>Sin interrupciones, sin ventanas emergentes, sin anuncios y sin compras dentro de la app. Solo puro y concentrado juego de rompecabezas.</p><h3 id="🌍-25-idiomas" tabindex="-1">🌍 <strong>25 idiomas</strong> <a class="header-anchor" href="#🌍-25-idiomas" aria-label="Permalink to “🌍 25 idiomas”">​</a></h3><p>Cambia de idioma en tiempo de ejecución desde Ajustes, sin reiniciar la app. Compatible con inglés, chino (simplificado y tradicional), japonés, coreano, francés, alemán, español, italiano, ruso, portugués, neerlandés, vietnamita, tailandés, hindi, turco, griego, finés, noruego, danés, húngaro, indonesio, malayo, ucraniano y alemán (Suiza).</p><h3 id="🔊-efectos-de-sonido" tabindex="-1">🔊 <strong>Efectos de sonido</strong> <a class="header-anchor" href="#🔊-efectos-de-sonido" aria-label="Permalink to “🔊 Efectos de sonido”">​</a></h3><p>Sutiles efectos de sonido al colocar números, al usar pistas, al cometer errores y al ganar; puedes activarlos o desactivarlos en Ajustes.</p><h3 id="🖨️-imprimir-puzles" tabindex="-1">🖨️ <strong>Imprimir puzles</strong> <a class="header-anchor" href="#🖨️-imprimir-puzles" aria-label="Permalink to “🖨️ Imprimir puzles”">​</a></h3><p>Imprime puzles directamente desde la app de Mac, con selección de dificultad y hojas de respuestas opcionales. Perfecto para resolver sin conexión con papel y lápiz.</p><h2 id="requisitos-del-sistema" tabindex="-1">Requisitos del sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to “Requisitos del sistema”">​</a></h2><ul><li><strong>iPhone/iPad</strong>: iOS/iPadOS 16.0 o posterior</li><li><strong>Mac</strong>: macOS 15.0 (Sequoia) o posterior (Apple Silicon)</li><li><strong>Almacenamiento</strong>: ~50 MB</li></ul><h2 id="privacidad" tabindex="-1">Privacidad <a class="header-anchor" href="#privacidad" aria-label="Permalink to “Privacidad”">​</a></h2><p>Sudoku está pensado para funcionar sin conexión en su jugabilidad principal. Todos los datos de juego se guardan localmente y se sincronizan solo con tu cuenta personal de iCloud. Sin anuncios, sin analíticas y sin rastreo de terceros. Las únicas funciones de red son la sincronización con iCloud, Game Center y una sección opcional de «Más apps» en Ajustes.</p><p>Consulta la <a href="/es/guide/privacy.html">Política de privacidad</a> para más detalles.</p><h2 id="primeros-pasos" tabindex="-1">Primeros pasos <a class="header-anchor" href="#primeros-pasos" aria-label="Permalink to “Primeros pasos”">​</a></h2><p>Si eres nuevo en Sudoku, empieza por la <a href="/es/guide/installation.html">Guía de instalación</a> para instalar la app en tu dispositivo.</p>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};